-- ===== joubu-chichibu =====
-- 上武秩父線（joubu-chichibu）の区間データ。tools/road.py build data/roads/joubu-chichibu.json で生成。手で編集しない。
-- schema.sql を実行したあとに、SQL Editor で全文を実行する。何度実行しても同じ状態になる。
-- 出典：線：© OpenStreetMap contributors（ODbL）
-- 出典：風早峠：国土地理院 地名データ
-- 出典：更木線分岐：秩父農林振興センターの位置図（令和8年6月1日）からの推定、誤差約150m
-- 出典：通行可否と規制：秩父農林振興センター 路線別詳細（令和8年5月20日現在）

set search_path = public, extensions;

insert into administrators (name, kind) values ('秩父農林振興センター', '県')
on conflict (name) do nothing;
insert into roads (name, kind) values ('上武秩父線', '林道')
on conflict (name) do nothing;

delete from segments where road_id = (select id from roads where name = '上武秩父線');

