-- ===== karibazaka =====
-- 苅場坂線（karibazaka）の区間データ。tools/road.py build data/roads/karibazaka.json で生成。手で編集しない。
-- schema.sql を実行したあとに、SQL Editor で全文を実行する。何度実行しても同じ状態になる。
-- 出典：線：© OpenStreetMap contributors（ODbL）
-- 出典：通行可否：川越農林振興センター 森林管理道の通行止め情報（2025年6月12日掲載、2026年10月11日閲覧）で通行可能な路線として明記

set search_path = public, extensions;

insert into administrators (name, kind) values ('川越農林振興センター', '県')
on conflict (name) do nothing;
insert into roads (name, kind) values ('苅場坂線', '林道')
on conflict (name) do nothing;

delete from segments where road_id = (select id from roads where name = '苅場坂線');

