-- ===== minoyama =====
-- 蓑山線（minoyama）の区間データ。tools/road.py build data/roads/minoyama.json で生成。手で編集しない。
-- schema.sql を実行したあとに、SQL Editor で全文を実行する。何度実行しても同じ状態になる。
-- 出典：線：© OpenStreetMap contributors（ODbL）
-- 出典：通行可否：秩父農林振興センター 森林管理道の通行制限情報（2026年10月11日閲覧）の通行制限路線に含まれないため「可」

set search_path = public, extensions;

insert into administrators (name, kind) values ('秩父農林振興センター', '県')
on conflict (name) do nothing;
insert into roads (name, kind) values ('蓑山線', '林道')
on conflict (name) do nothing;

delete from segments where road_id = (select id from roads where name = '蓑山線');

